package cn.zhuatech.energyai.controller; import cn.zhuatech.energyai.common.ApiResponse; import cn.zhuatech.energyai.dto.EnergyAiDto.*; import cn.zhuatech.energyai.service.EnergyAiService; import cn.zhuatech.energyai.service.AiRiskAssessmentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final EnergyAiService service;private final AiRiskAssessmentService risk;public WorkspaceController(EnergyAiService service,AiRiskAssessmentService risk){this.service=service;this.risk=risk;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("能源优化反馈已提交",service.report(id,request));}@PostMapping("/ai-risk-assessment") public ApiResponse<AiRiskAssessmentService.Result> assess(@Valid @RequestBody AiRiskAssessmentService.Request request){return ApiResponse.ok("AI 风险评估完成",risk.assess(request));}}
